using System.Text;
using Microsoft.CodeAnalysis.CSharp;

namespace Rocket.Surgery.LaunchPad.Analyzers.Api.Code;

/// <summary>
///     Writes the code model as the text of a generated file, in one pass, and shortens the fully qualified names the emitters write
///     (<c>global::System.Threading.Tasks.Task</c>) into the names a person would write, with the <c>using</c> directives that make them resolve:
///     <list type="bullet">
///         <item>a non-generic type becomes an alias: <c>using Task = global::System.Threading.Tasks.Task;</c> (an attribute under its
///         <c>…Attribute</c> name, written without the suffix);</item>
///         <item>a generic type imports its namespace (an alias can't be generic): <c>using System.Threading.Tasks;</c>;</item>
///         <item>a call into a static <c>…Extensions</c> class becomes an extension call (<c>endpoint.WithName("…")</c>) and imports the class's
///         namespace.</item>
///     </list>
/// </summary>
/// <remarks>
///     <para>
///         The layout is <c>NormalizeWhitespace</c>'s for the code LaunchPad writes: four spaces an indent, Allman braces, a blank line after a
///         closing brace unless another closing brace, <c>else</c> or a separator follows, initializers on one line inside an argument and one
///         element a line elsewhere. The text is the same as the earlier Roslyn-syntax version wrote.
///     </para>
///     <para>
///         Only names whose namespace is in <see cref="Namespaces" /> are shortened: the namespace part of a name has to be known exactly, or
///         <c>global::ProtoBuf.Meta.RuntimeTypeModel.Default</c> (a property) or <c>…ServiceLifetime.Scoped</c> (an enum member) would be taken
///         for a type. The user's own types stay fully qualified. A second name in a file that would shorten to the same name as a first stays
///         qualified; the members are read before the assembly attributes, and an extension call's receiver before its other arguments and
///         those before its method's type arguments, so which name comes first is decided as it always was.
///     </para>
/// </remarks>
internal sealed class CodePrinter
{
    private const string EndOfLine = "\n";
    private const char EndOfLineCharacter = '\n';
    private const string Header = "// <auto-generated/>\n#nullable enable\n#pragma warning disable CS1591\n\n";

    /// <summary>The namespaces whose types generated code may name short.</summary>
    private static readonly HashSet<string> Namespaces =
    [
        with(StringComparer.Ordinal),
        "Asp.Versioning",
        "Asp.Versioning.Builder",
        "ChannelMediator",
        "Foundatio.Mediator",
        "Grpc.Core",
        "HotChocolate",
        "HotChocolate.Authorization",
        "HotChocolate.Execution.Configuration",
        "HotChocolate.Resolvers",
        "HotChocolate.Types",
        "Immediate.Handlers.Shared",
        "Mediator",
        "Microsoft.AspNetCore.Authorization",
        "Microsoft.AspNetCore.Builder",
        "Microsoft.AspNetCore.Http",
        "Microsoft.AspNetCore.Http.HttpResults",
        "Microsoft.AspNetCore.Http.Metadata",
        "Microsoft.AspNetCore.Mvc",
        "Microsoft.AspNetCore.Routing",
        "Microsoft.CodeAnalysis",
        "Microsoft.Extensions.DependencyInjection",
        "Microsoft.Extensions.DependencyInjection.Extensions",
        "Microsoft.Extensions.Primitives",
        "ProtoBuf.Grpc",
        "ProtoBuf.Grpc.Configuration",
        "ProtoBuf.Grpc.Reflection",
        "ProtoBuf.Meta",
        "Rocket.Surgery.LaunchPad.Api.Generated.MinimalApi",
        "Rocket.Surgery.LaunchPad.Api.Generated.Mvc",
        "Rocket.Surgery.LaunchPad.Api.Generated.Grpc",
        "Rocket.Surgery.LaunchPad.Api.Generated.GraphQL",
        "System",
        "System.CodeDom.Compiler",
        "System.Collections.Generic",
        "System.Diagnostics.CodeAnalysis",
        "System.Globalization",
        "System.Linq",
        "System.Net",
        "System.Net.Http",
        "System.Net.Http.Json",
        "System.Reflection",
        "System.Runtime.CompilerServices",
        "System.Runtime.Serialization",
        "System.Text.Json",
        "System.Text.Json.Serialization",
        "System.Text.Json.Serialization.Metadata",
        "System.Threading",
        "System.Threading.Tasks",
        "ZeroAlloc.Mediator",
    ];

    // Every namespace in Namespaces and every dotted prefix of one: ProtoBuf.Grpc.Reflection makes ProtoBuf and ProtoBuf.Grpc namespaces too.
    private static readonly HashSet<string> NamespacesAndPrefixes = NamespacePrefixes();

    private static readonly string[] Indents = [.. Enumerable.Range(0, 16).Select(depth => new string(' ', depth * 4))];

    // alias name → the type it names; (generic name, arity) → its namespace.
    private readonly Dictionary<string, string> _aliases = [with(StringComparer.Ordinal)];
    private readonly Dictionary<(string Name, int Arity), string> _generics = [];
    private readonly SortedSet<string> _imports = [with(StringComparer.Ordinal)];
    private readonly Dictionary<CodeName, string?> _namespaces = [];

    private StringBuilder _text = new(8192);
    private int _depth;

    // Inside an argument an initializer is written on one line; a statement (a lambda's block) ends that.
    private bool _singleLine;

    // Whether the last qualified name written was shortened to a simple name.
    private bool _shortened;

    /// <summary>The text of a generated file: the header, the usings the names need, the assembly attributes, then the members.</summary>
    public static string Render(string? @namespace, IReadOnlyList<CodeMember> members, IEnumerable<string> usings, IReadOnlyList<CodeAttribute> assemblyAttributes)
    {
        var printer = new CodePrinter();
        foreach (var import in usings) printer._imports.Add(import);

        if (@namespace is { })
        {
            printer.Append("namespace ").Append(@namespace).Append(EndOfLineCharacter).Append('{').Append(EndOfLineCharacter);
            printer._depth = 1;
            printer.WriteMembers(members);
            printer.Append(EndOfLineCharacter).Append('}');
        }
        else
        {
            printer.WriteMembers(members);
        }

        var body = printer._text.ToString();
        var attributes = printer.Capture(
            () =>
            {
                foreach (var attribute in assemblyAttributes)
                {
                    printer.WriteAttributeList(attribute);
                    printer.Append(EndOfLineCharacter);
                }
            }
        );

        var text = new StringBuilder(Header.Length + body.Length + attributes.Length + 2048).Append(Header);
        var directives = printer._imports
                                .OrderBy(n => n.StartsWith("System", StringComparison.Ordinal) ? 0 : 1)
                                .ThenBy(n => n, StringComparer.Ordinal)
                                .Select(n => "using " + n + ";")
                                .Concat(printer._aliases.OrderBy(a => a.Key, StringComparer.Ordinal).Select(a => "using " + a.Key + " = " + a.Value + ";"))
                                .ToArray();
        if (directives.Length > 0) text.Append(string.Join(EndOfLine, directives)).Append(EndOfLineCharacter).Append(EndOfLineCharacter);
        return text.Append(attributes).Append(body).Append(EndOfLineCharacter).ToString();
    }

    // NormalizeWhitespace puts a space after the ? of a nullable type, wherever it is (string? x, (string? )null, int? []), unless the type is
    // a type argument (List<int?>): the next text written gets it, unless it starts with a space or a line break.
    private bool _spaceAfterNullable;

    private StringBuilder Append(string text)
    {
        if (_spaceAfterNullable)
        {
            _spaceAfterNullable = false;
            if (text.Length > 0 && text[0] is not ( ' ' or '\n' )) _text.Append(' ');
        }

        return _text.Append(text);
    }

    private StringBuilder Append(char text)
    {
        if (_spaceAfterNullable)
        {
            _spaceAfterNullable = false;
            if (text is not ( ' ' or '\n' )) _text.Append(' ');
        }

        return _text.Append(text);
    }

    private void Indent() => _text.Append(_depth < Indents.Length ? Indents[_depth] : new string(' ', _depth * 4));

    private void NewLine()
    {
        _spaceAfterNullable = false;
        _text.Append(EndOfLineCharacter);
        Indent();
    }

    // Writes into a buffer of its own and returns the text: a part written before the parts that come ahead of it in the file.
    private string Capture(Action write)
    {
        var outer = _text;
        _text = new StringBuilder();
        write();
        var captured = _text.ToString();
        _text = outer;
        return captured;
    }

    private void WriteMembers(IReadOnlyList<CodeMember> members)
    {
        for (var i = 0; i < members.Count; i++)
        {
            WriteMember(members[i]);
            if (i < members.Count - 1)
            {
                Append(EndOfLine);
                if (LineBreaksBetween(members[i], members[i + 1]) == 2) Append(EndOfLine);
            }
        }
    }

    // A blank line follows a member that ends with a closing brace, and a property, unless single-line properties follow one another; a
    // member that ends with a semicolon (a field, an expression-bodied or body-less method) is followed directly by the next.
    private static int LineBreaksBetween(CodeMember member, CodeMember next)
    {
        return  member is CodeProperty 
            ?  next is CodeProperty { AttributeLists.Count: 0 } ? 1 : 2 
            :  member is CodeTypeDeclaration or CodeConstructor or CodeMethod { Body: { } } ? 2 : 1;
    }

    private void WriteMember(CodeMember member)
    {
        if (member.Documentation is { } documentation)
        {
            foreach (var line in documentation.Split('\n'))
            {
                Indent();
                Append("/// ").Append(line.TrimEnd()).Append('\n');
            }
        }

        foreach (var attribute in member.AttributeLists)
        {
            Indent();
            WriteAttributeList(attribute);
            Append(EndOfLine);
        }

        Indent();
        foreach (var modifier in member.Modifiers.Kinds) Append(SyntaxFacts.GetText(modifier)).Append(' ');
        if (member is CodeTypeDeclaration type)
        {
            Append(type.Keyword).Append(' ').Append(type.Name);
            if (type.TypeParameters.Count > 0) Append('<').Append(string.Join(", ", type.TypeParameters)).Append('>');
            for (var i = 0; i < type.Bases.Count; i++)
            {
                Append(i == 0 ? " : " : ", ");
                WriteExpression(type.Bases[i]);
            }

            NewLine();
            Append('{');
            _depth++;
            if (type.Members.Count > 0)
            {
                Append(EndOfLine);
                WriteMembers(type.Members);
            }

            _depth--;
            NewLine();
            Append('}');
        }
        else if (member is CodeMethod method)
        {
            WriteExpression(method.ReturnType);
            Append(' ').Append(method.Name);
            WriteParameters(method.Parameters);
            WriteBody(method.Body, method.ExpressionBody);
        }
        else if (member is CodeConstructor constructor)
        {
            Append(constructor.Name);
            WriteParameters(constructor.Parameters);
            WriteBody(constructor.Body, null);
        }
        else if (member is CodeConversionOperator conversion)
        {
            Append("implicit operator ");
            WriteExpression(conversion.Type);
            WriteParameters(conversion.Parameters);
            WriteBody(null, conversion.ExpressionBody);
        }
        else if (member is CodeField field)
        {
            WriteExpression(field.Type);
            Append(' ').Append(field.Name);
            if (field.Value is { } value)
            {
                Append(" = ");
                WriteExpression(value);
            }

            Append(';');
        }
        else if (member is CodeProperty property)
        {
            WriteExpression(property.Type);
            Append(' ').Append(property.Name).Append(" { get; set; }");
            if (property.Initializer is { } initializer)
            {
                Append(" = ");
                WriteExpression(initializer);
                Append(';');
            }
        }
    }

    private void WriteBody(CodeBlock? body, CodeExpression? expressionBody)
    {
        if (body is { })
        {
            NewLine();
            WriteBlock(body);
        }
        else if (expressionBody is { })
        {
            Append(" => ");
            WriteExpression(expressionBody);
            Append(';');
        }
        else
        {
            Append(';');
        }
    }

    private void WriteParameters(IReadOnlyList<CodeParameter> parameters)
    {
        Append('(');
        for (var i = 0; i < parameters.Count; i++)
        {
            if (i > 0) Append(", ");
            var parameter = parameters[i];
            if (parameter.Attribute is { } attribute)
            {
                WriteAttributeList(attribute);
                Append(' ');
            }

            if (parameter.Modifier is { } modifier) Append(modifier).Append(' ');
            WriteExpression(parameter.Type);
            Append(' ').Append(parameter.Name);
            if (parameter.Default is { } value)
            {
                Append(" = ");
                WriteExpression(value);
            }
        }

        Append(')');
    }

    private void WriteAttributeList(CodeAttribute attribute)
    {
        Append('[');
        if (attribute.Target is { } target) Append(target).Append(": ");
        WriteName(attribute.Name, isAttribute: true);
        if (attribute.Arguments.Count > 0)
        {
            var wasSingleLine = _singleLine;
            _singleLine = true;
            Append('(');
            for (var i = 0; i < attribute.Arguments.Count; i++)
            {
                if (i > 0) Append(", ");
                if (attribute.Arguments[i].Name is { } name) Append(name).Append(" = ");
                WriteExpression(attribute.Arguments[i].Value);
            }

            Append(')');
            _singleLine = wasSingleLine;
        }

        Append(']');
    }

    // A block at the current depth: its braces there, its statements one deeper.
    private void WriteBlock(CodeBlock block)
    {
        var wasSingleLine = _singleLine;
        _singleLine = false;
        Append('{');
        _depth++;
        for (var i = 0; i < block.Statements.Count; i++)
        {
            Append(EndOfLine);
            if (i > 0 && EndsWithCloseBrace(block.Statements[i - 1])) Append(EndOfLine);
            Indent();
            WriteStatement(block.Statements[i]);
        }

        _depth--;
        NewLine();
        Append('}');
        _singleLine = wasSingleLine;
    }

    private static bool EndsWithCloseBrace(CodeStatement statement) =>
        statement switch
        {
            CodeBlock => true,
            CodeIf { Else: { } otherwise } => EndsWithCloseBrace(otherwise),
            CodeIf { Then: var then } => EndsWithCloseBrace(then),
            CodeForEach { Body: var body } => EndsWithCloseBrace(body),
            CodeLock { Body: var body } => EndsWithCloseBrace(body),
            _ => false,
        };

    // A statement, from the indentation already written.
    private void WriteStatement(CodeStatement statement)
    {
        switch (statement)
        {
            case CodeBlock block:
                WriteBlock(block);
                break;
            case CodeExpressionStatement expression:
                WriteExpression(expression.Expression);
                Append(';');
                break;
            case CodeLocalDeclaration local:
                if (local.IsUsing) Append("using ");
                WriteExpression(local.Type);
                Append(' ').Append(local.Name).Append(" = ");
                WriteExpression(local.Value);
                Append(';');
                break;
            case CodeKeywordStatement keyword:
                Append(keyword.Keyword);
                if (keyword.Value is { } value)
                {
                    Append(' ');
                    WriteExpression(value);
                }

                Append(';');
                break;
            case CodeIf ifStatement:
                Append("if (");
                WriteExpression(ifStatement.Condition);
                Append(')');
                WriteEmbedded(ifStatement.Then);
                if (ifStatement.Else is { } otherwise)
                {
                    NewLine();
                    Append("else");
                    if (otherwise is CodeIf)
                    {
                        Append(' ');
                        WriteStatement(otherwise);
                    }
                    else
                    {
                        WriteEmbedded(otherwise);
                    }
                }

                break;
            case CodeForEach forEach:
                if (forEach.IsAwait) Append("await ");
                Append("foreach (");
                WriteExpression(forEach.Type);
                Append(' ').Append(forEach.Item).Append(" in ");
                WriteExpression(forEach.Source);
                Append(')');
                WriteEmbedded(forEach.Body);
                break;
            case CodeLock lockStatement:
                Append("lock (");
                WriteExpression(lockStatement.Target);
                Append(')');
                WriteEmbedded(lockStatement.Body);
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(statement), statement.GetType().Name, "A statement the printer can't write.");
        }
    }

    // The statement of an if, else, foreach or lock: a block on the next line at the same depth, anything else on the next line one deeper.
    private void WriteEmbedded(CodeStatement statement)
    {
        if (statement is CodeBlock block)
        {
            NewLine();
            WriteBlock(block);
            return;
        }

        _depth++;
        NewLine();
        WriteStatement(statement);
        _depth--;
    }

    private void WriteArguments(IReadOnlyList<CodeArgument> arguments)
    {
        var wasSingleLine = _singleLine;
        _singleLine = true;
        Append('(');
        for (var i = 0; i < arguments.Count; i++)
        {
            if (i > 0) Append(", ");
            WriteArgument(arguments[i]);
        }

        Append(')');
        _singleLine = wasSingleLine;
    }

    private void WriteArgument(CodeArgument argument)
    {
        if (argument.OutVariable is { } variable)
        {
            Append("out var ").Append(variable);
            return;
        }

        if (argument.RefKind is { } refKind) Append(refKind).Append(' ');
        WriteExpression(argument.Expression!);
    }

    private void WriteExpression(CodeExpression expression)
    {
        switch (expression)
        {
            case CodeName name:
                WriteName(name, isAttribute: false);
                break;
            case CodePredefinedType predefined:
                Append(predefined.Keyword);
                break;
            case CodeNullableType nullable:
                WriteExpression(nullable.Element);
                Append('?');
                _spaceAfterNullable = true;
                break;
            case CodeArrayType array:
                WriteExpression(array.Element);
                // NormalizeWhitespace writes T[,] as T[, ]: a comma is followed by a space unless another comma follows.
                foreach (var rank in array.Ranks) Append('[').Append(rank == 0 ? "" : new string(',', rank) + " ").Append(']');
                break;
            case CodeTupleType tuple:
                Append('(');
                for (var i = 0; i < tuple.Elements.Count; i++)
                {
                    if (i > 0) Append(", ");
                    WriteExpression(tuple.Elements[i].Type);
                    if (tuple.Elements[i].Name is { } elementName) Append(' ').Append(elementName);
                }

                Append(')');
                break;
            case CodeLiteral literal:
                Append(literal.Text);
                break;
            case CodeMemberAccess access:
                WriteExpression(access.Target);
                Append('.');
                WriteName(access.Name, isAttribute: false);
                break;
            case CodeConditionalAccess conditional:
                WriteExpression(conditional.Target);
                Append("?.").Append(conditional.Name);
                if (conditional.Invoked) Append("()");
                break;
            case CodeInvocation invocation:
                WriteInvocation(invocation);
                break;
            case CodeElementAccess element:
                WriteExpression(element.Target);
                Append('[');
                WriteExpression(element.Index);
                Append(']');
                break;
            case CodeBinary binary:
                WriteExpression(binary.Left);
                Append(' ').Append(binary.Operator).Append(' ');
                WriteExpression(binary.Right);
                break;
            case CodeUnary { Postfix: true } unary:
                WriteExpression(unary.Operand);
                Append(unary.Operator);
                break;
            case CodeUnary unary:
                Append(unary.Operator);
                WriteExpression(unary.Operand);
                break;
            case CodeAwait awaited:
                Append("await ");
                WriteExpression(awaited.Operand);
                break;
            case CodeParenthesized parenthesized:
                Append('(');
                WriteExpression(parenthesized.Expression);
                Append(')');
                break;
            case CodeCast cast:
                Append('(');
                WriteExpression(cast.Type);
                Append(')');
                WriteExpression(cast.Expression);
                break;
            case CodeConditional conditionalExpression:
                WriteExpression(conditionalExpression.Condition);
                Append(" ? ");
                WriteExpression(conditionalExpression.WhenTrue);
                Append(" : ");
                WriteExpression(conditionalExpression.WhenFalse);
                break;
            case CodeTypeOf typeOf:
                Append("typeof(");
                WriteExpression(typeOf.Type);
                Append(')');
                break;
            case CodeObjectCreation creation:
                Append("new ");
                WriteExpression(creation.Type);
                WriteArguments(creation.Arguments);
                if (creation.Initializer is { } objectInitializer) WriteInitializer(objectInitializer);
                break;
            case CodeArrayCreation arrayCreation:
                Append("new ");
                WriteExpression(arrayCreation.Element);
                Append("[]");
                WriteInitializer(arrayCreation.Initializer);
                break;
            case CodeWith with:
                WriteExpression(with.Target);
                Append(" with");
                WriteInitializer(with.Initializer);
                break;
            case CodeLambda lambda:
                WriteLambda(lambda);
                break;
            case CodeIsPattern isPattern:
                WriteExpression(isPattern.Expression);
                Append(" is ");
                WritePattern(isPattern.Pattern);
                break;
            case CodeDeconstruction deconstruction:
                // NormalizeWhitespace writes var(a, b): var is an identifier there, and an identifier takes its parenthesis without a space.
                Append("var(").Append(string.Join(", ", deconstruction.Names)).Append(')');
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(expression), expression.GetType().Name, "An expression the printer can't write.");
        }
    }

    private void WritePattern(CodePattern pattern)
    {
        switch (pattern)
        {
            case CodeConstantPattern constant:
                WriteExpression(constant.Expression);
                break;
            case CodeDeclarationPattern declaration:
                WriteExpression(declaration.Type);
                Append(' ').Append(declaration.Name);
                break;
            case CodeVarPattern variable:
                Append("var ").Append(variable.Name);
                break;
            case CodeEmptyPropertyPattern property:
                Append("{ } ").Append(property.Name);
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(pattern), pattern.GetType().Name, "A pattern the printer can't write.");
        }
    }

    private void WriteLambda(CodeLambda lambda)
    {
        foreach (var modifier in lambda.Modifiers) Append(modifier).Append(' ');
        if (lambda.Parenthesized) Append('(').Append(string.Join(", ", lambda.Parameters)).Append(')');
        else Append(lambda.Parameters[0]);
        Append(" =>");
        if (lambda.Block is { } block)
        {
            // The block's braces sit at the depth of the statement around the lambda.
            NewLine();
            WriteBlock(block);
            return;
        }

        Append(' ');
        WriteExpression(lambda.ExpressionBody!);
    }

    // Inside an argument: { a, b } on the line. Elsewhere: the braces on their own lines, one element a line, one deeper.
    private void WriteInitializer(CodeInitializer initializer)
    {
        if (_singleLine)
        {
            Append(" {");
            for (var i = 0; i < initializer.Expressions.Count; i++)
            {
                Append(i == 0 ? " " : ", ");
                WriteExpression(initializer.Expressions[i]);
            }

            Append(" }");
            return;
        }

        NewLine();
        Append('{');
        _depth++;
        for (var i = 0; i < initializer.Expressions.Count; i++)
        {
            NewLine();
            WriteExpression(initializer.Expressions[i]);
            if (i < initializer.Expressions.Count - 1) Append(',');
        }

        _depth--;
        NewLine();
        Append('}');
    }

    private void WriteInvocation(CodeInvocation invocation)
    {
        // Extensions.Method(receiver, rest) → receiver.Method(rest), importing the extension class's namespace.
        if (invocation is { Target: CodeMemberAccess { Target: CodeQualifiedName type } access, Arguments: [var first, ..] arguments }
         && type.Right is CodeIdentifier { Text: var className }
         && className.EndsWith("Extensions", StringComparison.Ordinal)
         && Namespace(type.Left) is { } ns
         && Namespaces.Contains(ns)
         && first is { RefKind: null, OutVariable: null })
        {
            _imports.Add(ns);
            // The receiver, then the other arguments, then the method's name: the order the names in them are first seen.
            var receiver = Capture(() => WriteExpression(first.Expression!));
            var receiverKind = first.Expression!;
            var shortened = _shortened;
            var rest = Capture(() => WriteArguments([.. arguments.Skip(1)]));
            var method = Capture(() => WriteName(access.Name, isAttribute: false));
            var bare = receiverKind is CodeIdentifier
                                    or CodeGenericName
                                    or CodeMemberAccess
                                    or CodeInvocation
                                    or CodeElementAccess
                                    or CodeParenthesized
                                    or CodeLiteral
                                    or CodeObjectCreation
                    || ( receiverKind is CodeQualifiedName && shortened );
            if (bare) Append(receiver);
            else Append('(').Append(receiver).Append(')');
            Append('.').Append(method).Append(rest);
            return;
        }

        WriteExpression(invocation.Target);
        WriteArguments(invocation.Arguments);
    }

    private void WriteName(CodeName name, bool isAttribute)
    {
        _shortened = false;
        switch (name)
        {
            case CodeIdentifier identifier:
                Append(identifier.Text);
                break;
            case CodeGenericName generic:
                WriteGeneric(generic);
                break;
            case CodeAliasQualifiedName aliasQualified:
                Append(aliasQualified.Alias).Append("::").Append(aliasQualified.Name.Text);
                break;
            case CodeQualifiedName qualified:
                WriteQualified(qualified, isAttribute);
                break;
            default:
                throw new ArgumentOutOfRangeException(nameof(name), name.GetType().Name, "A name the printer can't write.");
        }
    }

    private void WriteGeneric(CodeGenericName generic)
    {
        Append(generic.Text).Append('<');
        for (var i = 0; i < generic.Arguments.Count; i++)
        {
            if (i > 0) Append(", ");
            if (generic.Arguments[i] is CodeNullableType nullable)
            {
                WriteExpression(nullable.Element);
                Append('?');
            }
            else
            {
                WriteExpression(generic.Arguments[i]);
            }
        }

        Append('>');
    }

    private void WriteQualified(CodeQualifiedName node, bool isAttribute)
    {
        if (Namespace(node.Left) is { } ns && Namespaces.Contains(ns))
        {
            if (node.Right is CodeGenericName generic)
            {
                var key = (generic.Text, generic.Arguments.Count);
                if (!_generics.TryGetValue(key, out var existing) || existing == ns)
                {
                    _generics[key] = ns;
                    _imports.Add(ns);
                    WriteGeneric(generic);
                    _shortened = true;
                    return;
                }
            }
            // A known namespace, or the start of one (ProtoBuf.Grpc.Reflection under ProtoBuf.Grpc), isn't a type to alias.
            else if (node.Right is CodeIdentifier identifier && !IsNamespace(ns + "." + identifier.Text))
            {
                var name = identifier.Text;
                var alias = isAttribute && !name.EndsWith("Attribute", StringComparison.Ordinal) ? name + "Attribute" : name;
                var target = "global::" + ns + "." + alias;
                if (_aliases.TryGetValue(alias, out var named) && named != target)
                {
                    // Taken by another type: the name stays as the emitter wrote it.
                    WriteUnshortened(node);
                    return;
                }

                _aliases[alias] = target;
                Append(isAttribute ? alias[..^"Attribute".Length] : alias);
                _shortened = true;
                return;
            }
        }

        WriteName(node.Left, isAttribute: false);
        Append('.');
        WriteName(node.Right, isAttribute: false);
        _shortened = false;
    }

    // A name as written, without shortening any part of it.
    private void WriteUnshortened(CodeName name)
    {
        switch (name)
        {
            case CodeQualifiedName qualified:
                WriteUnshortened(qualified.Left);
                Append('.');
                WriteUnshortened(qualified.Right);
                break;
            case CodeGenericName generic:
                Append(generic.Text).Append('<');
                for (var i = 0; i < generic.Arguments.Count; i++)
                {
                    if (i > 0) Append(", ");
                    if (generic.Arguments[i] is CodeName argument) WriteUnshortened(argument);
                    else WriteExpression(generic.Arguments[i]);
                    _spaceAfterNullable = false;
                }

                Append('>');
                break;
            default:
                WriteName(name, isAttribute: false);
                break;
        }

        _shortened = false;
    }

    private static bool IsNamespace(string name) => NamespacesAndPrefixes.Contains(name);

    private static HashSet<string> NamespacePrefixes()
    {
        var prefixes = new HashSet<string>(StringComparer.Ordinal);
        foreach (var name in Namespaces)
        {
            prefixes.Add(name);
            for (var dot = name.IndexOf('.'); dot >= 0; dot = name.IndexOf('.', dot + 1)) prefixes.Add(name[..dot]);
        }

        return prefixes;
    }

    // The dotted namespace a name stands for, without global::; null for anything else, or under a prefix LaunchPad doesn't know.
    private string? Namespace(CodeName name)
    {
        if (_namespaces.TryGetValue(name, out var known)) return known;
        var result = name switch
        {
            CodeAliasQualifiedName { Alias: "global", Name: var root } => root.Text,
            CodeQualifiedName { Right: CodeIdentifier right } qualified when Namespace(qualified.Left) is { } left && IsNamespace(left) => left + "." + right.Text,
            _ => null,
        };
        _namespaces[name] = result;
        return result;
    }
}
